class Solution {
  public long countOperationsToEmptyArray(int[] nums) {
    int n = nums.length;
    Integer[] order = new Integer[n];
    for (int i = 0; i < n; i++) order[i] = i;
    Arrays.sort(
        order,
        (a, b) -> nums[a] != nums[b] ? Integer.compare(nums[a], nums[b]) : Integer.compare(a, b));
    int[] tree = new int[n + 1];
    for (int i = 1; i <= n; i++) {
      tree[i] += 1;
      int parent = i + (i & -i);
      if (parent <= n) tree[parent] += tree[i];
    }
    long operations = 0;
    int position = 0; // where the front of the array currently is
    for (int i = 0; i < n; ) {
      int j = i;
      while (j < n && nums[order[j]] == nums[order[i]]) j++;
      // equal values are removed in cyclic order starting from the front
      List<Integer> group = new ArrayList<>();
      for (int t = i; t < j; t++) if (order[t] >= position) group.add(order[t]);
      for (int t = i; t < j; t++) if (order[t] < position) group.add(order[t]);
      for (int p : group) {
        if (p >= position) operations += query(tree, p + 1) - query(tree, position);
        else operations += query(tree, n) - query(tree, position) + query(tree, p + 1);
        for (int x = p + 1; x <= n; x += x & -x) tree[x]--;
        position = p;
      }
      i = j;
    }
    return operations;
  }

  private int query(int[] tree, int i) {
    int sum = 0;
    for (; i > 0; i -= i & -i) sum += tree[i];
    return sum;
  }
}
